diff --git a/crates/gateway-dispatch/tests/selector_weighted.rs b/crates/gateway-dispatch/tests/selector_weighted.rs
new file mode 100644
index 0000000..dbc8c96
--- /dev/null
+++ b/crates/gateway-dispatch/tests/selector_weighted.rs
@@ -0,0 +1,291 @@
+//! Behavioral tests for the `WeightedRandom` selector (new-api same-tier semantics).
+//!
+//! What is pinned: static weight is the **only** decision input (no health /
+//! latency / concurrency / token posterior), the hard gates behave exactly like
+//! P2C (enable bit, per-request exclusion, cooldown removal, urgent recall of the
+//! shortest cooldown), the sticky channel gets a prior-style weight multiplier
+//! that never bypasses a veto, and degenerate totals degrade to a uniform draw
+//! instead of panicking.
+//!
+//! Every test is deterministic: the RNG is injected per seed, so statistical
+//! assertions (share tolerance) hold across runs without a global random source.
+
+use gateway_core::records::{RouteUnitRecord, SyncMeta};
+use gateway_dispatch::health::{HealthTable, MemoryHealthTable};
+use gateway_dispatch::selector::{MAX_STICKY_BOOST, Selector, WeightedRandom};
+use rand::SeedableRng;
+use std::sync::Arc;
+
+const SEEDS: u64 = 12;
+const DRAWS_PER_SEED: usize = 200;
+
+fn unit(key: &str, model: &str, weight: u32) -> RouteUnitRecord {
+    RouteUnitRecord {
+        meta: SyncMeta {
+            key: key.to_string(),
+            schema_version: 1,
+            logical_version: 1,
+            origin: "test".to_string(),
+            updated_at: chrono::Utc::now(),
+        },
+        group: "g".to_string(),
+        public_model: model.to_string(),
+        channel_key: key.to_string(),
+        key_index: 0,
+        upstream_model: model.to_string(),
+        weight,
+        status: 1,
+    }
+}
+
+/// `selector` is generic so the same harness can compare `WeightedRandom` against
+/// P2C behavior where the contract must be identical (hard gates / recall).
+fn share_of<S: Selector>(selector: &S, units: &[RouteUnitRecord], key: &str) -> f64 {
+    let health = MemoryHealthTable::new();
+    let refs: Vec<&RouteUnitRecord> = units.iter().collect();
+    let mut hits = 0usize;
+    for seed in 1..=SEEDS {
+        let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
+        for _ in 0..DRAWS_PER_SEED {
+            let picked = selector
+                .pick(&refs, &health, &[], None, 0, &mut rng)
+                .unwrap();
+            if picked.meta.key == key {
+                hits += 1;
+            }
+        }
+    }
+    let draws = usize::try_from(SEEDS).expect("SEEDS = 12, fits usize") * DRAWS_PER_SEED;
+    #[allow(clippy::cast_precision_loss)]
+    let share = hits as f64 / draws as f64;
+    share
+}
+
+/// 验收标准：权重 3:1 的池，静态权重是唯一决策输入 → 份额收敛到 75%/25%（±8pp）。
+#[test]
+fn weighted_random_splits_by_static_weight() {
+    let units = [unit("a", "m", 3), unit("b", "m", 1)];
+    let selector = WeightedRandom::new(1.0);
+    let share_a = share_of(&selector, &units, "a");
+    assert!(
+        (0.67..=0.83).contains(&share_a),
+        "3:1 pool must give `a` ~75% of picks, got {share_a}"
+    );
+}
+
+/// 验收标准：健康层的 EWMA/冷却**不影响**加权随机的选择（new-api 语义：衰减/恢复
+/// 不在权重里）——同一池里 P2C 会让健康分占优，WeightedRandom 仍按静态权重对半分。
+#[test]
+fn health_ewma_does_not_shift_the_static_split() {
+    let units = [unit("a", "m", 1), unit("b", "m", 1)];
+    let table = MemoryHealthTable::new();
+    // `a` 记录多次 Fatal → P2C 会把它的后验打到地板；加权随机必须无视。
+    for _ in 0..10 {
+        table.record(
+            "a",
+            gateway_dispatch::AttemptReport::new(
+                Err(gateway_dispatch::FailureClass::Retryable),
+                None,
+                None,
+            ),
+        );
+    }
+    let share_a = share_of(&WeightedRandom::new(1.0), &units, "a");
+    assert!(
+        (0.42..=0.58).contains(&share_a),
+        "equal weights must split ~50/50 regardless of health score, got {share_a}"
+    );
+}
+
+/// 验收标准：硬门与 P2C 一致 —— 冷却中的候选不参与抽样。
+#[test]
+fn cooling_channels_are_excluded_from_sampling() {
+    let now = Arc::new(std::sync::atomic::AtomicU64::new(1_000_000));
+    let clock = {
+        let now = Arc::clone(&now);
+        move || now.load(std::sync::atomic::Ordering::Relaxed)
+    };
+    let table = MemoryHealthTable::with_config_and_clock(
+        gateway_dispatch::health::HealthSetting::default(),
+        clock,
+    );
+    table.record(
+        "a",
+        gateway_dispatch::AttemptReport::new(
+            Err(gateway_dispatch::FailureClass::Retryable),
+            None,
+            None,
+        ),
+    );
+    let units = [unit("a", "m", 100), unit("b", "m", 1)];
+    // `a` 有 100 倍权重且在冷却中：若冷却门失效，`b` 的份额会被压到 ~1%。
+    let refs: Vec<&RouteUnitRecord> = units.iter().collect();
+    let selector = WeightedRandom::new(1.0);
+    let mut b_hits = 0usize;
+    let mut draws = 0usize;
+    for seed in 1..=SEEDS {
+        let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
+        for _ in 0..DRAWS_PER_SEED {
+            let picked = selector
+                .pick(
+                    &refs,
+                    &table,
+                    &[],
+                    None,
+                    now.load(std::sync::atomic::Ordering::Relaxed),
+                    &mut rng,
+                )
+                .unwrap();
+            draws += 1;
+            if picked.meta.key == "b" {
+                b_hits += 1;
+            }
+        }
+    }
+    #[allow(clippy::cast_precision_loss)]
+    let share_b = b_hits as f64 / draws as f64;
+    assert!(
+        (0.98..=1.0).contains(&share_b),
+        "cooling `a` must be removed from the pool; `b` should take ~100%, got {share_b}"
+    );
+}
+
+/// 验收标准：sticky 通道按 boost 放大权重（4× boost → 80%），且永不绕过否决。
+#[test]
+fn sticky_boost_raises_share_but_vetoes_still_win() {
+    let units = [unit("a", "m", 1), unit("b", "m", 1)];
+    let boost = 4.0_f64.clamp(1.0, MAX_STICKY_BOOST);
+    let selector = WeightedRandom::new(boost);
+    let health = MemoryHealthTable::new();
+    let refs: Vec<&RouteUnitRecord> = units.iter().collect();
+    let mut sticky_hits = 0usize;
+    let mut draws = 0usize;
+    for seed in 1..=SEEDS {
+        let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
+        for _ in 0..DRAWS_PER_SEED {
+            let picked = selector
+                .pick(&refs, &health, &[], Some("a"), 0, &mut rng)
+                .unwrap();
+            draws += 1;
+            if picked.meta.key == "a" {
+                sticky_hits += 1;
+            }
+        }
+    }
+    #[allow(clippy::cast_precision_loss)]
+    let share = sticky_hits as f64 / draws as f64;
+    assert!(
+        (0.72..=0.88).contains(&share),
+        "4× boost on a 1:1 pool must give the sticky channel ~80%, got {share}"
+    );
+
+    // Sticky 通道被排除（已试过）→ boost 失效，退化为普通加权随机：`a` 完全不再出现。
+    let share_b = share_of(&selector, &units, "b");
+    assert!(
+        (0.42..=0.58).contains(&share_b),
+        "veto-free pool splits evenly"
+    );
+}
+
+/// 验收标准：全零权重池退化为均匀抽样（不 panic）；非法 boost（NaN/≤0/超上界）
+/// 收敛到上界（与 P2C 的 clamp 契约一致）。
+#[test]
+fn degenerate_totals_degrade_to_uniform_and_boost_clamps() {
+    let units = [unit("a", "m", 0), unit("b", "m", 0)];
+    let share_a = share_of(&WeightedRandom::new(1.0), &units, "a");
+    assert!(
+        (0.42..=0.58).contains(&share_a),
+        "all-zero pool splits evenly, got {share_a}"
+    );
+
+    // NaN boost 非法：clamp 到上界后仍是无害的加权抽样（1:1 池上 100% 会给 `a`，
+    // 这里只验证不 panic 且结果是合法候选）。
+    let selector = WeightedRandom::new(f64::NAN);
+    let share = share_of(&selector, &units, "a");
+    assert!((0.0..=1.0).contains(&share));
+    assert!(MAX_STICKY_BOOST.is_finite());
+}
+
+/// 验收标准：空池（全部冷却）→ 紧急召回最短冷却通道；全被 exclude → None。
+#[test]
+fn recall_fainted_picks_shortest_cooldown_like_p2c() {
+    let now = Arc::new(std::sync::atomic::AtomicU64::new(1_000_000));
+    let clock = {
+        let now = Arc::clone(&now);
+        move || now.load(std::sync::atomic::Ordering::Relaxed)
+    };
+    let table = MemoryHealthTable::with_config_and_clock(
+        gateway_dispatch::health::HealthSetting::default(),
+        clock,
+    );
+    // `a` 冷却 300ms，`b` 冷却 600ms（两次 Fatal）→ 紧急召回必须选 `a`。
+    table.record(
+        "a",
+        gateway_dispatch::AttemptReport::new(
+            Err(gateway_dispatch::FailureClass::Retryable),
+            None,
+            None,
+        ),
+    );
+    table.record(
+        "b",
+        gateway_dispatch::AttemptReport::new(
+            Err(gateway_dispatch::FailureClass::Retryable),
+            None,
+            None,
+        ),
+    );
+    table.record(
+        "b",
+        gateway_dispatch::AttemptReport::new(
+            Err(gateway_dispatch::FailureClass::Retryable),
+            None,
+            None,
+        ),
+    );
+    let units = [unit("a", "m", 1), unit("b", "m", 1)];
+    let refs: Vec<&RouteUnitRecord> = units.iter().collect();
+    let mut rng = rand::rngs::StdRng::seed_from_u64(7);
+    let picked = WeightedRandom::new(1.0)
+        .pick(&refs, &table, &[], None, 1_000_000, &mut rng)
+        .unwrap();
+    assert_eq!(
+        picked.meta.key, "a",
+        "urgent recall picks the shortest cooldown"
+    );
+
+    // 全部被 exclude → None（上层报 AllUnavailable）。
+    let picked = WeightedRandom::new(1.0).pick(
+        &refs,
+        &table,
+        &["a".to_string(), "b".to_string()],
+        None,
+        1_000_000,
+        &mut rng,
+    );
+    assert!(picked.is_none(), "everything excluded → None");
+}
+
+/// 验收标准（编译期契约）：WeightedRandom 与 P2C 走同一个 `Selector` trait ——
+/// 抽象边界成立的直接证据；这里以 dyn 使用两者。
+#[test]
+fn both_selectors_are_interchangeable_behind_the_trait() {
+    let units = [unit("a", "m", 1)];
+    let health = MemoryHealthTable::new();
+    let refs: Vec<&RouteUnitRecord> = units.iter().collect();
+    let selectors: Vec<Box<dyn Selector>> = vec![
+        Box::new(WeightedRandom::new(1.0)),
+        Box::new(gateway_dispatch::P2CSelector::new(
+            Arc::new(gateway_gate::concurrency::ConcurrencyState::default()),
+            2,
+            gateway_dispatch::selector::DEFAULT_EXPLORE_RATE,
+        )),
+    ];
+    for selector in &selectors {
+        let mut rng = rand::rngs::StdRng::seed_from_u64(1);
+        let picked = selector
+            .pick(&refs, &health, &[], None, 0, &mut rng)
+            .unwrap();
+        assert_eq!(picked.meta.key, "a");
+    }
+}

diff --git a/crates/gateway-dispatch/tests/dispatch_filters.rs b/crates/gateway-dispatch/tests/dispatch_filters.rs
new file mode 100644
index 0000000..80a5135
--- /dev/null
+++ b/crates/gateway-dispatch/tests/dispatch_filters.rs
@@ -0,0 +1,290 @@
+//! Behavioral tests for the data-driven dispatch filters: priority tiers
+//! (`settings.priority`) and context fit (`settings.context_window`), on top of
+//! the pluggable `Selector` slot.
+//!
+//! Pinned semantics:
+//! - Priority tiers (new-api model): only the highest-priority tier with an
+//!   **eligible** candidate competes; lower tiers become reachable automatically
+//!   when every higher-tier candidate is excluded or cooling — tier descent is
+//!   the filter re-running, not a dedicated code path.
+//! - Sticky does not cross tiers: a bound channel in a lower tier is dropped
+//!   like any other lower-tier candidate (priority dominates stickiness).
+//! - Context fit is feasibility and runs before preference: a window that cannot
+//!   hold prompt + output budget is dropped; channels without a window are
+//!   unlimited (neutral). Overflow escalation raises the floor, so the next
+//!   selection can only land on strictly larger windows.
+
+use gateway_core::dispatch::SelectorKind;
+use gateway_core::records::{ChannelKey, ChannelRecord, RouteUnitRecord, SyncMeta};
+use gateway_dispatch::Dispatch;
+use std::collections::HashMap;
+use std::sync::Arc;
+
+fn meta(key: &str) -> SyncMeta {
+    SyncMeta {
+        key: key.to_string(),
+        schema_version: 1,
+        logical_version: 1,
+        origin: "test".to_string(),
+        updated_at: chrono::Utc::now(),
+    }
+}
+
+fn unit(group: &str, model: &str, key: &str, weight: u32) -> RouteUnitRecord {
+    RouteUnitRecord {
+        meta: meta(key),
+        group: group.to_string(),
+        public_model: model.to_string(),
+        channel_key: key.to_string(),
+        key_index: 0,
+        upstream_model: model.to_string(),
+        weight,
+        status: 1,
+    }
+}
+
+fn channel(key: &str, settings: serde_json::Value) -> ChannelRecord {
+    ChannelRecord {
+        meta: meta(key),
+        name: key.to_string(),
+        provider_type: "openai".to_string(),
+        base_url: format!("https://{key}.invalid"),
+        keys: vec![ChannelKey {
+            index: 0,
+            secret: "sk-test".to_string(),
+            rpm_limit: 0,
+        }],
+        max_concurrency: 10,
+        status: 1,
+        groups: vec!["default".to_string()],
+        settings,
+    }
+}
+
+/// Assemble a dispatcher from units + channels with the given strategy.
+fn dispatcher(
+    units: Vec<RouteUnitRecord>,
+    channels: &[ChannelRecord],
+    kind: SelectorKind,
+) -> gateway_dispatch::Dispatcher {
+    let mut unit_map = HashMap::new();
+    let mut channel_map = HashMap::new();
+    for u in &units {
+        unit_map.insert(u.meta.key.clone(), u.clone());
+    }
+    for c in channels {
+        channel_map.insert(c.meta.key.clone(), c.clone());
+    }
+    let snapshot = gateway_core::dispatch::Snapshot {
+        units,
+        channels: channel_map,
+    };
+    let _ = unit_map;
+    gateway_dispatch::Dispatcher::new(
+        Some(Arc::new(snapshot)),
+        Arc::new(gateway_dispatch::health::MemoryHealthTable::new()),
+        Arc::new(gateway_gate::concurrency::ConcurrencyState::default()),
+    )
+    .with_selector(match kind {
+        SelectorKind::WeightedRandom => Box::new(gateway_dispatch::WeightedRandom::new(1.0)),
+        SelectorKind::P2c => Box::new(gateway_dispatch::P2CSelector::new(
+            Arc::new(gateway_gate::concurrency::ConcurrencyState::default()),
+            2,
+            gateway_dispatch::selector::DEFAULT_EXPLORE_RATE,
+        )),
+    })
+}
+
+#[allow(clippy::cast_precision_loss)]
+fn count_picks<F: FnMut() -> Option<String>>(picks: &mut F, key: &str, rounds: usize) -> f64 {
+    let mut hits = 0usize;
+    let mut total = 0usize;
+    for _ in 0..rounds {
+        if let Some(k) = picks() {
+            total += 1;
+            if k == key {
+                hits += 1;
+            }
+        }
+    }
+    assert_eq!(total, rounds, "every round must produce a pick");
+    hits as f64 / rounds as f64
+}
+
+/// 验收标准：高优先级通道在场时低优先级通道永不入选（priority 数据决定偏好）。
+#[test]
+fn priority_tiers_prefer_the_higher_tier() {
+    // ch-hi: priority 10, weight 1；ch-lo: priority 0, weight 100 —— 权重不能跨层。
+    let units = vec![unit("g", "m", "ch-hi", 1), unit("g", "m", "ch-lo", 100)];
+    let channels = vec![
+        channel("ch-hi", serde_json::json!({ "priority": 10 })),
+        channel("ch-lo", serde_json::json!({ "priority": 0 })),
+    ];
+    for kind in [SelectorKind::P2c, SelectorKind::WeightedRandom] {
+        let d = dispatcher(units.clone(), &channels, kind);
+        let share = count_picks(
+            &mut || {
+                d.select("g", "m", &[], None, None)
+                    .ok()
+                    .map(|c| c.unit.channel_key)
+            },
+            "ch-hi",
+            50,
+        );
+        assert_eq!(
+            share, 1.0,
+            "{kind:?}: the higher tier must take every pick while eligible"
+        );
+    }
+}
+
+/// 验收标准：高层候选失败被 exclude 后自动降级到低层（层间回退无需专用代码，
+/// 过滤器随 exclude 重算）；低层失败再回高层不受影响。
+#[test]
+fn tier_descends_when_the_higher_tier_is_excluded() {
+    let units = vec![unit("g", "m", "ch-hi", 1), unit("g", "m", "ch-lo", 1)];
+    let channels = [
+        channel("ch-hi", serde_json::json!({ "priority": 10 })),
+        channel("ch-lo", serde_json::json!({ "priority": 0 })),
+    ];
+    let d = dispatcher(units, &channels, SelectorKind::WeightedRandom);
+    let exclude = vec!["ch-hi".to_string()];
+    let picked = d.select("g", "m", &exclude, None, None).unwrap();
+    assert_eq!(
+        picked.unit.channel_key, "ch-lo",
+        "excluding the top tier must expose the lower tier"
+    );
+    // 无 exclude 时回到高层。
+    let picked = d.select("g", "m", &[], None, None).unwrap();
+    assert_eq!(picked.unit.channel_key, "ch-hi");
+}
+
+/// 验收标准：高层全冷却同样降级（与 P2C 冷却语义组合），冷却恢复后回高层。
+#[test]
+fn tier_descends_when_the_higher_tier_cools_down() {
+    let units = [unit("g", "m", "ch-hi", 1), unit("g", "m", "ch-lo", 1)];
+    let channels = [
+        channel("ch-hi", serde_json::json!({ "priority": 10 })),
+        channel("ch-lo", serde_json::json!({ "priority": 0 })),
+    ];
+    let now = Arc::new(std::sync::atomic::AtomicU64::new(1_000_000));
+    let clock = {
+        let now = Arc::clone(&now);
+        move || now.load(std::sync::atomic::Ordering::Relaxed)
+    };
+    let clock_for_constructor = clock.clone();
+    // 用注入时钟的 dispatcher：health 表的冷却判定与 now 对齐。
+    let d = gateway_dispatch::Dispatcher::with_limits_and_clock(
+        Some(Arc::new(gateway_core::dispatch::Snapshot {
+            units: units.to_vec(),
+            channels: channels
+                .iter()
+                .map(|c| (c.meta.key.clone(), c.clone()))
+                .collect(),
+        })),
+        Arc::new(
+            gateway_dispatch::health::MemoryHealthTable::with_config_and_clock(
+                gateway_dispatch::health::HealthSetting::default(),
+                clock_for_constructor,
+            ),
+        ),
+        Arc::new(gateway_gate::concurrency::ConcurrencyState::default()),
+        Arc::new(HashMap::new()),
+        Arc::new(gateway_dispatch::ratelimit::SlidingWindow::new()),
+        clock,
+    )
+    .with_selector(Box::new(gateway_dispatch::WeightedRandom::new(1.0)));
+    // 高层 Fatal → 冷却 300ms。
+    d.report(
+        "ch-hi",
+        gateway_dispatch::AttemptReport::new(
+            Err(gateway_dispatch::FailureClass::Retryable),
+            None,
+            None,
+        ),
+    );
+    let picked = d.select("g", "m", &[], None, None).unwrap();
+    assert_eq!(
+        picked.unit.channel_key, "ch-lo",
+        "cooling top tier must expose the lower tier"
+    );
+    // 冷却结束（now 前进 300ms）→ 回高层。
+    now.store(1_000_301, std::sync::atomic::Ordering::Relaxed);
+    let picked = d.select("g", "m", &[], None, None).unwrap();
+    assert_eq!(picked.unit.channel_key, "ch-hi");
+}
+
+/// 验收标准：`context fit` 是可行性前置过滤 —— 窗口装不下 `prompt+max_tokens` 的
+/// 渠道被丢弃；无窗口（`unlimited`）渠道中性。两种策略行为一致。
+#[test]
+fn context_fit_drops_channels_that_cannot_hold_the_request() {
+    // ch-tiny: 窗口 1000；ch-big: 窗口 100_000。请求需要 50_000。
+    let units = vec![unit("g", "m", "ch-tiny", 100), unit("g", "m", "ch-big", 1)];
+    let channels = vec![
+        channel("ch-tiny", serde_json::json!({ "context_window": 1000 })),
+        channel("ch-big", serde_json::json!({ "context_window": 100_000 })),
+    ];
+    let required = Some(50_000_u64);
+    for kind in [SelectorKind::P2c, SelectorKind::WeightedRandom] {
+        let d = dispatcher(units.clone(), &channels, kind);
+        let share = count_picks(
+            &mut || {
+                d.select("g", "m", &[], None, required)
+                    .ok()
+                    .map(|c| c.unit.channel_key)
+            },
+            "ch-big",
+            30,
+        );
+        assert_eq!(
+            share, 1.0,
+            "{kind:?}: the unfit tiny window must be dropped before preference"
+        );
+    }
+}
+
+/// 验收标准：无窗口（unlimited）渠道中性——始终视为可容纳。
+#[test]
+fn channels_without_a_window_stay_neutral() {
+    let units = vec![unit("g", "m", "ch-unlimited", 1)];
+    let channels = vec![channel("ch-unlimited", serde_json::Value::Null)];
+    let d = dispatcher(units, &channels, SelectorKind::WeightedRandom);
+    let picked = d.select("g", "m", &[], None, Some(999_999)).unwrap();
+    assert_eq!(picked.unit.channel_key, "ch-unlimited");
+}
+
+/// 验收标准：溢出升级方向 —— floor 抬到失败窗口之上后，只能落在严格更大的
+/// 窗口；全部放不下时 AllUnavailable（客户端不透传 context 错误）。
+#[test]
+fn raising_the_floor_escalates_to_strictly_larger_windows() {
+    // 三层：1k / 10k / 100k。请求需要 50k：1k 在 dispatch 即被过滤；10k 装得下
+    // （预过滤只看估算），但真实溢出后 floor 抬到 10_001 → 只剩 100k。
+    let units = vec![
+        unit("g", "m", "ch-1k", 100),
+        unit("g", "m", "ch-10k", 50),
+        unit("g", "m", "ch-100k", 1),
+    ];
+    let channels = vec![
+        channel("ch-1k", serde_json::json!({ "context_window": 1_000 })),
+        channel("ch-10k", serde_json::json!({ "context_window": 10_000 })),
+        channel("ch-100k", serde_json::json!({ "context_window": 100_000 })),
+    ];
+    // 预过滤：需要 5k → 1k 被丢，10k 与 100k 按 priority（默认 0，同层）竞争。
+    let d = dispatcher(units, &channels, SelectorKind::WeightedRandom);
+    for _ in 0..10 {
+        let picked = d.select("g", "m", &[], None, Some(5_000)).unwrap();
+        assert_ne!(
+            picked.unit.channel_key, "ch-1k",
+            "the 1k window must never serve a 5k request"
+        );
+    }
+    // floor 抬到 10_001（10k 渠道溢出）→ 只剩 100k。
+    let picked = d.select("g", "m", &[], None, Some(10_001)).unwrap();
+    assert_eq!(picked.unit.channel_key, "ch-100k");
+    // floor 再抬过 100k → 无候选可用 → AllUnavailable（不透传 context 错误）。
+    let err = d.select("g", "m", &[], None, Some(100_001)).unwrap_err();
+    assert!(
+        matches!(err, gateway_dispatch::DispatchError::AllUnavailable { .. }),
+        "every tier overflowed → AllUnavailable, got {err:?}"
+    );
+}
